js="""const mensJerseyModal=document.getElementById('mensJerseyModal'),mensJerseyMain=document.getElementById('mensJerseyMain'),mensJerseyThumbs=[...document.querySelectorAll('#mensJerseyModal .jersey-thumb')],mensJerseyColourName=document.getElementById('mensJerseyColourName'),mensJerseyColors=[...document.querySelectorAll('#mensJerseyModal .jersey-colors .sports-color')];let mensJerseyIndex=12;function showMensJerseyImage(i){mensJerseyIndex=(i+mensJerseyThumbs.length)%mensJerseyThumbs.length;const t=mensJerseyThumbs[mensJerseyIndex];mensJerseyMain.src=t.dataset.img;mensJerseyMain.alt=t.dataset.label||t.querySelector('img').alt;mensJerseyThumbs.forEach(x=>x.classList.remove('active'));t.classList.add('active');const colour=t.dataset.colour||'';mensJerseyColourName.textContent=colour;mensJerseyColors.forEach(x=>x.classList.toggle('active',x.getAttribute('aria-label')===colour))}document.getElementById('openMensJersey').onclick=()=>{mensJerseyModal.classList.add('open');document.body.style.overflow='hidden';showMensJerseyImage(mensJerseyIndex)};function closeMensJerseyModal(){mensJerseyModal.classList.remove('open');document.body.style.overflow=''}document.getElementById('closeMensJersey').onclick=closeMensJerseyModal;mensJerseyModal.addEventListener('click',e=>{if(e.target===mensJerseyModal)closeMensJerseyModal()});mensJerseyThumbs.forEach((t,i)=>t.onclick=()=>showMensJerseyImage(i));mensJerseyColors.forEach(c=>c.onclick=()=>showMensJerseyImage(Number(c.dataset.index)));document.getElementById('mensJerseyPrev').onclick=()=>showMensJerseyImage(mensJerseyIndex-1);document.getElementById('mensJerseyNext').onclick=()=>showMensJerseyImage(mensJerseyIndex+1);document.querySelectorAll('#mensJerseyModal .jersey-size').forEach(b=>b.onclick=()=>{document.querySelectorAll('#mensJerseyModal .jersey-size').forEach(x=>x.classList.remove('active'));b.classList.add('active')});"""
